p-sleep-that-can-be-aborted.starter:
// Resolve after ms milliseconds. If signal is already aborted, reject at once with signal.reason; if it aborts
// while waiting, clear the timer and reject with signal.reason.
function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  throw new Error('Not implemented');
}

p-sleep-that-can-be-aborted.solution:
function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason);
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal?.reason);
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

