p-debounce-with-cancel-and-flush.starter:
// Return a function that calls fn once, `wait` ms after the last call, with the latest arguments. It also has
// cancel() (drop the pending call) and flush() (run the pending call now, if there is one).
function debounce<A extends unknown[]>(fn: (...args: A) => void, wait: number): ((...args: A) => void) & { cancel(): void; flush(): void } {
  throw new Error('Not implemented');
}

p-debounce-with-cancel-and-flush.solution:
function debounce<A extends unknown[]>(fn: (...args: A) => void, wait: number) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let lastArgs: A | undefined;

  const run = () => {
    timer = undefined;
    const args = lastArgs;
    lastArgs = undefined;
    if (args) fn(...args);
  };
  const debounced = (...args: A) => {
    lastArgs = args;
    clearTimeout(timer);
    timer = setTimeout(run, wait);
  };
  debounced.cancel = () => {
    clearTimeout(timer);
    timer = undefined;
    lastArgs = undefined;
  };
  debounced.flush = () => {
    if (timer === undefined) return;
    clearTimeout(timer);
    run();
  };
  return debounced;
}

p-debounce-with-cancel-and-flush.tests:
import { mock } from 'node:test';
mock.timers.enable({ apis: ['setTimeout'] });
const calls: string[] = [];
const search = debounce((q: string) => calls.push(q), 300);
search('a');
mock.timers.tick(200);
search('ag');
mock.timers.tick(200);
search('age');
assert.deepEqual(calls, []); // still typing
mock.timers.tick(300);
assert.deepEqual(calls, ['age']); // one call, latest arguments

search('x');
search.cancel();
mock.timers.tick(1_000);
assert.deepEqual(calls, ['age']);
search('flushed');
search.flush();
assert.deepEqual(calls, ['age', 'flushed']);
mock.timers.tick(1_000);
assert.equal(calls.length, 2); // flush did not leave a second call behind
mock.timers.reset();

