p-throttle-with-leading-and-trailing-cal.starter:
// Return a function that runs fn at once on the first call, then collapses calls for `wait` ms: the latest call
// made during the window runs at its end and starts a new window.
function throttle<A extends unknown[]>(fn: (...args: A) => void, wait: number): (...args: A) => void {
  throw new Error('Not implemented');
}

p-throttle-with-leading-and-trailing-cal.solution:
function throttle<A extends unknown[]>(fn: (...args: A) => void, wait: number) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let pending: A | undefined;

  const openWindow = () => {
    timer = setTimeout(() => {
      if (pending) {
        const args = pending;
        pending = undefined;
        fn(...args);
        openWindow();
      } else {
        timer = undefined;
      }
    }, wait);
  };

  return (...args: A) => {
    if (timer === undefined) {
      fn(...args);
      openWindow();
    } else {
      pending = args;
    }
  };
}

p-throttle-with-leading-and-trailing-cal.tests:
import { mock } from 'node:test';
mock.timers.enable({ apis: ['setTimeout'] });
const seen: number[] = [];
const onScroll = throttle((y: number) => seen.push(y), 100);
onScroll(0); // leading: runs now
mock.timers.tick(10);
onScroll(10);
mock.timers.tick(40);
onScroll(50); // replaces 10
assert.deepEqual(seen, [0]);
mock.timers.tick(50); // t = 100: trailing call with the latest value
assert.deepEqual(seen, [0, 50]);
mock.timers.tick(100); // t = 200: nothing pending, window closes
onScroll(300);
assert.deepEqual(seen, [0, 50, 300]); // a new leading call
mock.timers.reset();

