p-implement-promise-all.starter:
// Behave like Promise.all without calling it: results in input order, plain values allowed, [] for an empty
// array, and reject with the first rejection.
function promiseAll<T>(values: readonly (T | PromiseLike<T>)[]): Promise<T[]> {
  throw new Error('Not implemented');
}

p-implement-promise-all.solution:
function promiseAll<T>(values: readonly (T | PromiseLike<T>)[]): Promise<T[]> {
  return new Promise((resolve, reject) => {
    const results = new Array<T>(values.length);
    let remaining = values.length;
    if (remaining === 0) return resolve(results);
    values.forEach((value, i) => {
      Promise.resolve(value).then((v) => {
        results[i] = v;
        if (--remaining === 0) resolve(results);
      }, reject);
    });
  });
}

