p-run-async-work-with-a-concurrency-limi.prelude:
// Given: tick() waits one turn of the event loop, and fakeApi(id) is a fake request that takes a few turns and
// records the most calls in flight at once in `peak`.
const tick = () => new Promise<void>((resolve) => setImmediate(resolve));
let active = 0;
let peak = 0;
const fakeApi = async (id: number) => {
  active++;
  peak = Math.max(peak, active);
  for (let i = 0; i < (id % 3) + 1; i++) await tick(); // different durations
  active--;
  return `record-${id}`;
};

p-run-async-work-with-a-concurrency-limi.starter:
// Run fn over items with at most `limit` calls in flight and resolve with the results in input order. Reject with
// the first error and start no new items after it. Reject with a RangeError if limit is not a positive integer.
async function mapLimit<T, R>(items: readonly T[], limit: number, fn: (item: T, index: number) => Promise<R>): Promise<R[]> {
  throw new Error('Not implemented');
}

p-run-async-work-with-a-concurrency-limi.solution:
async function mapLimit<T, R>(items: readonly T[], limit: number, fn: (item: T, index: number) => Promise<R>): Promise<R[]> {
  if (!Number.isInteger(limit) || limit < 1) throw new RangeError('limit must be a positive integer');
  const results = new Array<R>(items.length);
  let next = 0;
  let failed = false;
  const worker = async () => {
    while (!failed && next < items.length) {
      const i = next++;
      try {
        results[i] = await fn(items[i], i);
      } catch (err) {
        failed = true; // no new items start; calls already in flight finish on their own
        throw err;
      }
    }
  };
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return results;
}

p-run-async-work-with-a-concurrency-limi.tests:
const ids = Array.from({ length: 20 }, (_, i) => i);
const out = await mapLimit(ids, 5, fakeApi);
assert.equal(peak, 5);
assert.deepEqual(out, ids.map((i) => `record-${i}`));
assert.deepEqual(await mapLimit([], 3, fakeApi), []);
await assert.rejects(
  mapLimit([1, 2, 3], 2, async (n) => {
    if (n === 2) throw new Error('bad record 2');
    return n;
  }),
  { message: 'bad record 2' },
);
await assert.rejects(mapLimit([1], 0, fakeApi), RangeError);
// After the first failure no new items start.
const started: number[] = [];
await assert.rejects(
  mapLimit(Array.from({ length: 10 }, (_, i) => i), 2, async (n) => {
    started.push(n);
    await tick();
    if (n === 1) throw new Error('bad record 1');
    return n;
  }),
  { message: 'bad record 1' },
);
await tick();
await tick();
assert.deepEqual(started, [0, 1, 2]);

