p-retry-with-exponential-backoff-and-ful.prelude:
// Given: an HTTP error, a retry policy (429 and 5xx are worth retrying), and a fake sleep that records each delay
// instead of waiting.
class HttpError extends Error {
  status: number;
  constructor(status: number) {
    super(`HTTP ${status}`);
    this.status = status;
  }
}
const retryable = (err: unknown) => err instanceof HttpError && (err.status === 429 || err.status >= 500);
const delays: number[] = [];
const fakeSleep = async (ms: number) => void delays.push(ms);

p-retry-with-exponential-backoff-and-ful.starter:
type RetryOptions = {
  retries: number;
  baseMs: number;
  maxMs: number;
  shouldRetry?: (err: unknown) => boolean;
  signal?: AbortSignal;
  sleep?: (ms: number, signal?: AbortSignal) => Promise<void>;
  random?: () => number;
};

// Call fn(attempt), counting attempts from 0. When it throws an error that shouldRetry accepts (default: any error),
// wait Math.floor(random() * Math.min(maxMs, baseMs * 2 ** attempt)) ms with options.sleep, then try again, up to
// `retries` extra attempts; after that, rethrow the last error. Stop with the signal's reason as soon as `signal`
// aborts, even in the middle of a wait. The default sleep must really wait and honour the signal (like the first
// problem's sleep); random defaults to Math.random.
async function retry<T>(fn: (attempt: number) => Promise<T>, options: RetryOptions): Promise<T> {
  throw new Error('Not implemented');
}

p-retry-with-exponential-backoff-and-ful.solution:
type RetryOptions = {
  retries: number;
  baseMs: number;
  maxMs: number;
  shouldRetry?: (err: unknown) => boolean;
  signal?: AbortSignal;
  sleep?: (ms: number, signal?: AbortSignal) => Promise<void>;
  random?: () => number;
};
// The abortable sleep from the first problem.
const realSleep = (ms: number, signal?: AbortSignal) =>
  new Promise<void>((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason);
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal?.reason);
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    signal?.addEventListener('abort', onAbort, { once: true });
  });
async function retry<T>(fn: (attempt: number) => Promise<T>, options: RetryOptions): Promise<T> {
  const { retries, baseMs, maxMs, shouldRetry = () => true, signal, sleep = realSleep, random = Math.random } = options;
  for (let attempt = 0; ; attempt++) {
    signal?.throwIfAborted();
    try {
      return await fn(attempt);
    } catch (err) {
      if (attempt >= retries || !shouldRetry(err)) throw err;
      const cap = Math.min(maxMs, baseMs * 2 ** attempt);
      await sleep(Math.floor(random() * cap), signal);
    }
  }
}

p-retry-with-exponential-backoff-and-ful.tests:
let calls = 0;
const result = await retry(
  async () => {
    calls++;
    if (calls < 3) throw new HttpError(503);
