p-memoize-an-async-function-with-in-flig.starter:
// Return a memoised fn with a clear() method: concurrent calls with the same key share one promise, later calls
// reuse the result, and a rejected call is forgotten so the next call tries again. A failure must only remove its
// own entry (after clear(), a newer request may own the key).
function memoizeAsync<A extends unknown[], R>(fn: (...args: A) => Promise<R>, key: (...args: A) => string = (...args) => JSON.stringify(args)): ((...args: A) => Promise<R>) & { clear(): void } {
  throw new Error('Not implemented');
}

p-memoize-an-async-function-with-in-flig.solution:
function memoizeAsync<A extends unknown[], R>(fn: (...args: A) => Promise<R>, key: (...args: A) => string = (...args) => JSON.stringify(args)) {
  const cache = new Map<string, Promise<R>>();
  const memoized = (...args: A): Promise<R> => {
    const k = key(...args);
    const hit = cache.get(k);
    if (hit) return hit;
    const p = fn(...args);
    cache.set(k, p);
    p.catch(() => {
      // Only remove our own entry: after clear(), a newer request may own this key.
      if (cache.get(k) === p) cache.delete(k);
    });
    return p;
  };
  memoized.clear = () => cache.clear();
  return memoized;
}

