p-latest-request-wins-cancel-stale-searc.starter:
// Return a wrapper that calls fn(signal, ...args). Each new call aborts the previous call's signal, and a
// superseded call rejects with a DOMException named 'AbortError', even if fn ignores its signal.
function latest<A extends unknown[], R>(fn: (signal: AbortSignal, ...args: A) => Promise<R>): (...args: A) => Promise<R> {
  throw new Error('Not implemented');
}

p-latest-request-wins-cancel-stale-searc.solution:
function latest<A extends unknown[], R>(fn: (signal: AbortSignal, ...args: A) => Promise<R>) {
  let current: AbortController | undefined;
  return async (...args: A): Promise<R> => {
    current?.abort(new DOMException('Superseded by a newer call', 'AbortError'));
    const controller = new AbortController();
    current = controller;
    const result = await fn(controller.signal, ...args);
    controller.signal.throwIfAborted();
    return result;
  };
}

