// Given: make(name) returns a task that logs its start and its end around one turn of the event loop.
const log: string[] = [];
const make = (name: string) => async () => {
  log.push(`start ${name}`);
  await new Promise<void>((resolve) => setImmediate(resolve));
  log.push(`end ${name}`);
  return name;
};

p-run-async-tasks-in-series.starter:
// Run the tasks one after another (each starts after the previous one finished) and resolve with their results
// in order. The last tests show why tasks.map((t) => t()) is not the same thing.
async function series<T>(tasks: readonly (() => Promise<T>)[]): Promise<T[]> {
  throw new Error('Not implemented');
}

p-run-async-tasks-in-series.solution:
async function series<T>(tasks: readonly (() => Promise<T>)[]): Promise<T[]> {
  const results: T[] = [];
  for (const task of tasks) results.push(await task());
  return results;
}

p-run-async-tasks-in-series.tests:
assert.deepEqual(await series([make('a'), make('b')]), ['a', 'b']);
assert.deepEqual(log, ['start a', 'end a', 'start b', 'end b']);
log.length = 0;
await Promise.all([make('a'), make('b')].map((t) => t()));
assert.deepEqual(log, ['start a', 'start b', 'end a', 'end b']); // parallel: both started first
assert.deepEqual(await series([]), []);

